        New-Item -ItemType File -Path $profilePath -Force | Out-Null
        Write-Host "Created new profile at $profilePath"
    }
    # Open folder or file in editor
    if ($OpenFolder) {
        & $Editor (Split-Path -Parent $profilePath) *> $null
    } else {
        & $Editor $profilePath *> $null
    }
